Lemma tstep LB cr (fx fx1 : FPState) R R1 (pc pc1 : Z) M M1 model K (sp x n y m B bm : Z) :
  hi_heap HI LB cr M (m_vmmaps model) -> m_halted model = None -> m_vm_lazy model = [] -> 0x7fff80000000 <= hl_sptop L ->
  hl_ceil L <= sp - 128 -> sp <= hl_sptop L -> (n = 0 \/ (hl_ceil L <= x /\ x + n <= hl_sptop L)) ->
  (m = 0 \/ (In (B, bm) LB /\ B <= y /\ y + m <= B + bm)) ->
